class Grant(BaseModel):
    """
    Scoped access for an agent: which sources, which senses, and optionally a time window. An agent key sees only what its grants allow; a request outside them fails with forbidden_sense (ADR 0024).
    """

    model_config = ConfigDict(
        extra='allow',
        populate_by_name=True,
    )
    id: Annotated[str, Field(pattern='^grt_[0-9A-HJKMNP-TV-Z]{26}$')]
    agent_id: str
    source_ids: Annotated[list[str], Field(min_length=1)]
    senses: Annotated[list[Sense], Field(min_length=1)]
    abilities: list[Literal['watch', 'history']]
    """
    What else the agent may do on these sources (ADR 0048): `watch` sets watches; `history` reads recorded data older than the last two hours (events, memory search, playback, clips, conversations). Live access (look, ask, listen, read environment) comes with the senses. Default both.
    """
    window: Window | None = None
    """
    Live access (look, ask, listen) only inside the window; recorded data only from inside it. Either end may be open.
    """
    created_at: AwareDatetime


class Webhook(BaseModel):
    model_config = ConfigDict(
        extra='allow',
        populate_by_name=True,
    )
    id: Annotated[str, Field(pattern='^whk_[0-9A-HJKMNP-TV-Z]{26}$')]
    url: str
    events: Annotated[list[str], Field(min_length=1)]
    secret: str | None = None
    """
    Signing secret (whsec_…), returned only on creation. Deliveries carry Senseplane-Signature: t=<unix>,v1=<hex HMAC-SHA256(secret, t + '.' + body)>.
    """
    created_at: AwareDatetime


class Channel(BaseModel):
    """
    A chat in a messaging app (Telegram) linked to the workspace (ADR 0059). Watches that list it in `notify` send their events there, and people in the chat can ask about the cameras, as the channel's agent (its grants apply).
    """

    model_config = ConfigDict(
        extra='allow',
        populate_by_name=True,
    )
    id: str
    """
    chn_…
    """
    kind: Literal['telegram']
    name: str
    """
    The chat's title, or the person's name for a private chat.
    """
    chat_type: Literal['private', 'group']
    status: Literal['active', 'blocked']
    """
    `blocked`: the bot was blocked or removed from the chat; link it again to use it.
    """
    snapshots: bool
    """
    Send the event's snapshot with each alert. A snapshot sent to Telegram is stored by Telegram.
    """
    can_ask: bool
    """
    Whether people in the chat can ask questions.
    """
    muted_until: AwareDatetime | None
    """
    Alerts are skipped until then.
    """
    agent_id: str
    """
    The agent the chat asks as; its grants decide which cameras and senses answers use.
    """
    created_at: AwareDatetime


