class Usage(BaseModel):
    """
    Usage meters for an account over a period (default: the current UTC month). Deployments can enforce allowances through the quota provider; the open-source default is unlimited (ADR 0025).
    """

    model_config = ConfigDict(
        extra='allow',
        populate_by_name=True,
    )
    period: Period
    recording_hours: float
    """
    camera_minutes / 60
    """
    storage_gb_days: float
    """
    storage_gb_hours / 24
    """
    frames_analysed: int
    vlm_calls: int
    """
    Vision model calls (part of ai_checks)
    """
    quotas: dict[str, float] | None = None
    """
    Limits from the quota provider (absent = unlimited)
    """
    camera_minutes: float
    """
    Minutes of video ingested (recorded), all sources
    """
    camera_minutes_by_resolution: dict[str, float]
    """
    Camera-minutes per recorded resolution: `720p` (up to 1280×720), `1080p` (up to 1920×1080), `other`
    """
    camera_minutes_by_source: dict[str, float] | None = None
    storage_gb_hours: float
    """
    Stored GB (raw, clips, snapshots) sampled hourly; divide by 730 for GB-months
    """
    storage_gb_month: float | None = None
    ai_checks: int
    """
    Model calls (vision and text)
    """
    ai_checks_by_kind: AiChecksByKind
    sources: Sources
    by_day: list[ByDayItem] | None = None
    live_view_minutes: float | None = None
    """
    Viewer-minutes of live view (one person watching one source for one minute), all sources
    """
    live_view_minutes_by_source: dict[str, float] | None = None
    live_viewers_now: Annotated[int | None, Field(ge=0)] = None
    """
    People watching live view right now across the account (sessions joined and not ended; ADR 0042)
    """


