class Account(BaseModel):
    model_config = ConfigDict(
        extra='allow',
        populate_by_name=True,
    )
    id: str
    name: str
    time_zone: str
    """
    IANA time zone for watch schedules and answers like "this morning" (default UTC).
    """
    retention_days: Annotated[int | None, Field(ge=1)]
    """
    Days mode: raw footage older than this is deleted; null keeps it until deleted.
    """
    retention_max_days: Annotated[int | None, Field(ge=1)]
    """
    Maximum allowed for this account; null means no limit (self-host).
    """
    created_at: AwareDatetime
    retention_mode: Literal['days', 'fill']
    """
    days (default): keep raw footage for retention_days. fill: keep as much raw footage as retention_max_bytes (or the deployment's storage cap) holds, deleting the oldest first. Clips, snapshots and events are kept until deleted in both modes and count towards storage.
    """
    retention_max_bytes: Annotated[int | None, Field(ge=1)] = None
    """
    Byte cap for fill mode; null uses the deployment's storage cap, if any.
    """
    storage: Storage | None = None
    """
    Stored bytes and recent growth.
    """
    limits: Limits | None = None
    """
    Limits from the deployment's quota provider (null = unlimited). Self-host default: live view on, everything else null. Usage allowances are per month when the provider sets a monthly one, else per day.
    """
    plan_label: str | None = None
    """
    Display name of the account's plan, if the deployment has plans
    """


