class Watch(BaseModel):
    model_config = ConfigDict(
        extra='allow',
        populate_by_name=True,
    )
    id: Annotated[str, Field(pattern='^wat_[0-9A-HJKMNP-TV-Z]{26}$')]
    instruction: Annotated[str, Field(max_length=500, min_length=3)]
    sources: Annotated[list[str], Field(min_length=1)]
    mode: Literal['alert', 'track']
    """
    alert: the watch posts watch.triggered events and notifies its destinations. track: it only records activities, to answer questions later (ADR 0057). Both record activities.
    """
    compiled: Compiled
    estimate: Estimate
    status: Literal['active', 'paused', 'needs_zone', 'expired']
    warnings: list[str]
    created_at: AwareDatetime
    expires_at: AwareDatetime | None = None
    """
    When the watch stops by itself (from `duration_minutes` or `expires_at` at creation); null means never. An expired watch has status `expired`.
    """
    notify: Annotated[list[Destination], Field(max_length=20)]
    """
    Where watch.triggered events go (ADR 0043). Empty: every webhook subscribed to watch.triggered. Otherwise only these webhooks and agent inboxes. The Events feed always has every event.
    """
    active_hours: WatchSchedule | None
    """
    When the watch may fire, in a time zone; null means always (ADR 0043). Applies on top of `compiled.active_hours`.
    """


